/** Fellow-exporter contracts are financial commitments, never warehouse movements. */
function dt_permission(array $u,string $action='View'):bool {
    return tt_user_can_module_action($u,'Directors','exporter-trading',$action);
}
function dt_workspace_permission(array $u,string $action='View',string $origin='Directors'):bool {return $origin==='Accounts'?tt_user_can_module_action($u,'Accounts','group-reports',$action):dt_permission($u,$action);}
function dt_cost_permission(array $u,string $action='View'):bool {return tt_user_can_module_action($u,'Directors','costing',$action)||dt_permission($u,$action);}
function dt_entity(mixed $v):string {$v=strtoupper(gm_text($v,3));if(!in_array($v,['TTI','BRM'],true))throw new DomainException('Select TTI or BRM company books.');return $v;}
function dt_enum(mixed $v,array $options,string $label):string {$v=gm_text($v,100);if(!in_array($v,$options,true))throw new DomainException('Select '.$label.'.');return $v;}
function dt_positive(mixed $v,string $label):float {$v=gm_number($v,$label);if($v<=0)throw new DomainException($label.' must be positive.');return $v;}
function dt_id(array $rows,string $prefix):string {do{$id=$prefix.'-'.bin2hex(random_bytes(9));}while(isset($rows[$id]));return $id;}
function dt_profiles():array {return json_decode((string)file_get_contents(__DIR__.'/../directors/costing-profiles.json'),true,512,JSON_THROW_ON_ERROR);}
function dt_rules(array $s,string $entity,string $date):?array {
    $best=null;foreach((array)($s['directorCostingRules']??[]) as $r)if($r['entity']===$entity&&$r['effectiveFrom']<=$date&&(!$best||$r['effectiveFrom']>$best['effectiveFrom']))$best=$r;return $best;
}
/** Daily principal integration handles repayments and multiple drawdowns without compounding. */
function dt_finance(array $s,string $entity,array $i):array {
    if(empty($i['enabled']))return ['costPKR'=>0.,'days'=>0,'basis'=>'Financing off'];
    $from=gm_date($i['from']??'');$to=gm_date($i['to']??'');$days=(int)(new DateTimeImmutable($from))->diff(new DateTimeImmutable($to))->format('%r%a');if($days<0||$days>3660)throw new DomainException('Financing end must follow start within ten years.');
    $rate=gm_number($i['annualPct']??null,'annual financing rate')/100;if($rate>1)throw new DomainException('Review the annual financing percentage.');$basis=gm_number($i['dayBasis']??365,'bank day-count basis');if(!in_array($basis,[360.,365.,366.],true))throw new DomainException('Use the bank day-count basis 360, 365 or 366.');
    $fees=gm_number($i['feesPKR']??0,'facility charges');$id=gm_text($i['facilityId']??'',120);$balanceDays=0.;
    if($id!==''){
        $facility=$s['bankFacilities'][$id]??null;if(!$facility||$facility['entity']!==$entity||$facility['currency']!=='PKR')throw new DomainException('Select a PKR finance facility in these books.');
        $moves=[];foreach((array)($s['journals']??[]) as $j){if(($j['entity']??'')!==$entity||($j['status']??'')!=='Posted'||($j['date']??'')>=$to)continue;
            foreach((array)($j['lines']??[]) as $l)if(($l['account']??'')==='2610'&&($l['bankFacilityId']??$j['meta']['bankFacilityId']??'')===$id){$date=gm_date($j['date']);$moves[$date]=($moves[$date]??0)+(float)($l['credit']??0)-(float)($l['debit']??0);}
        }ksort($moves);$balance=0.;foreach($moves as $date=>$move){if($date<=$from)$balance+=$move;}
        for($d=new DateTimeImmutable($from);$d<new DateTimeImmutable($to);$d=$d->modify('+1 day')){$date=$d->format('Y-m-d');if($date>$from)$balance+=$moves[$date]??0;if($balance<-.005)throw new DomainException('Finance principal needs reconciliation.');$balanceDays+=max(0,$balance);}
        $share=gm_number($i['allocationPct']??null,'shipment share of facility financing');if($share>100)throw new DomainException('Facility allocation cannot exceed 100%.');$balanceDays*=$share/100;$label='Posted daily facility principal; shipment share '.$share.'%';
    }else{$balanceDays=gm_number($i['principalPKR']??null,'principal financed')*$days;$label='Entered principal estimate';}
    return ['costPKR'=>round($balanceDays*$rate/$basis+$fees,4),'days'=>$days,'basis'=>$label,'balanceDaysPKR'=>$balanceDays];
}
/** A fixed period budget is spread over actual/reviewed input kg, never output kg. */
function dt_milling_rate(array $i):float {
    $basis=dt_enum($i['millingCostBasis']??'PER_KG',['PER_KG','TOTAL_INPUT'],'milling cost basis');
    if($basis==='TOTAL_INPUT')return gm_number($i['millingTotalPKR']??null,'total milling budget')/dt_positive($i['millingInputKg']??null,'milling input kilograms');
    return gm_number($i['millingPKRPerKg']??0,'milling charge');
}
function dt_cost(array $s,string $entity,array $i):array {
