    $wht=gm_number($rule['whtPct']??$i['whtPct']??null,'WHT assumption')/100;$bank=gm_number($rule['bankPct']??$i['bankPct']??null,'bank deduction assumption')/100;if($wht+$bank>=1)throw new DomainException('Total deductions must be below 100%.');$netFX=$fx*(1-$wht-$bank);
    $commodity=dt_enum($i['commodity']??'RICE',['RICE','CORN'],'Rice or Maize');$factor=match(dt_enum($i['purchaseUnit']??'KG',['KG','MAUND','MT'],'purchase unit')){'KG'=>1000.,'MAUND'=>25.,'MT'=>1.};
    $raw=gm_number($i['cashPrice']??null,'cash purchase price')*$factor;$credit=isset($i['creditPrice'])&&$i['creditPrice']!==''?gm_number($i['creditPrice'],'udhaar purchase price')*$factor:null;
    $mill=dt_milling_rate($i)*1000;$processing=gm_number($i['processingPKRPerKg']??0,'separate processing charge')*1000;if($commodity==='CORN'&&$mill>0)throw new DomainException('Maize has no rice milling charge.');$sum=0.;$recovery=0.;$byvalue=0.;$names=[];
    foreach((array)($i['outputs']??[]) as $r){$name=gm_text($r['product']??'',80);if($name===''||isset($names[strtoupper($name)]))throw new DomainException('Use unique output names.');$names[strtoupper($name)]=true;$yield=gm_number($r['recoveryPct']??null,'output recovery');$sum+=$yield;$kind=dt_enum($r['kind']??'',['finished','byproduct','waste'],'output kind');
        if($kind==='finished')$recovery+=$yield/100;elseif($kind==='byproduct'&&$yield>0){if($commodity==='CORN')throw new DomainException('Direct-loading maize has no milling by-products.');$byvalue+=10*$yield*gm_number($r['ratePKRPerKg']??null,$name.' price');}elseif($kind==='waste'&&(float)($r['ratePKRPerKg']??0)!==0.)throw new DomainException('Loss has no sale value.');
    }if(abs($sum-100)>.00001||$recovery<=0)throw new DomainException('Finished output, by-products and loss must total 100%.');
    $basis=dt_enum($i['incoterm']??'FOB',['FOB','CNF','CIF'],'shipment basis');$qty=dt_positive($i['quantityMT']??null,'finished quantity');$otherPKR=gm_number($i['otherFOBPKRPerMT']??0,'other FOB in PKR');$otherUSD=gm_number($i['otherFOBUSDPerMT']??0,'other FOB in USD');
    $packing=gm_number($i['packingAdjustment']??null,'packing adjustment',true);$packingCurrency=dt_enum($i['packingCurrency']??'USD',['USD','PKR'],'packing currency');if($packingCurrency==='PKR')$otherPKR+=$packing;else$otherUSD+=$packing;
    $thc=gm_number($i['thcUSDPerMT']??0,'THC');$freight=$basis==='FOB'?0:gm_number($i['freightUSDPerContainer']??null,'freight per container')/dt_positive($i['payloadMT']??null,'container payload');$insurance=$basis==='CIF'?gm_number($i['insuranceUSDPerMT']??null,'insurance'):0;
    $otherUSD+=!empty($i['masterBagEnabled'])?gm_number($i['masterBagUSDPerMT']??null,'master bag addition per MT'):0;
    $finance=dt_finance($s,$entity,(array)($i['finance']??[]));$out=[];
    foreach(['cash'=>$raw,'udhaar'=>$credit,'financedCash'=>$raw] as $k=>$purchase){if($purchase===null){$out[$k]=null;continue;}$material=($purchase+$mill+$processing-$byvalue)/$recovery;if($material<0)throw new DomainException('By-product credit exceeds purchase and milling cost.');$funding=$k==='financedCash'?$finance['costPKR']/$qty:0;$cost=($material+$otherPKR+$funding)/$netFX+$otherUSD+$thc+$freight+$insurance;if($cost<0)throw new DomainException('Review the packing adjustment.');$out[$k]=['materialPKRPerMT'=>round($material,4),'financingPKRPerMT'=>round($funding,4),'costUSDPerMT'=>round($cost,4),'costPKRPerMT'=>round($cost*$fx,4),'shipmentUSD'=>round($cost*$qty,2)];}
    return ['date'=>$date,'effectiveFX'=>$netFX,'finishedRecoveryPct'=>$recovery*100,'millingPKRPerInputKg'=>$mill/1000,'processingPKRPerInputKg'=>$processing/1000,'byproductCreditPKRPerInputMT'=>$byvalue,'finance'=>$finance,'costs'=>$out,'ruleId'=>$rule['id']??'Entered assumptions','basis'=>'Cost only; entered rates and dated rule snapshot. No accounting posting.'];
}
function dt_lots(array $root,string $entity):array {
    $out=[];$contracts=array_column((array)($root['contracts']??[]),null,'ref');
    foreach(tt_accounts_shipment_rows($root,$entity) as $row){$sh=null;foreach((array)($root['shipments']??[]) as $r)if(($r['id']??'')===$row['id'])$sh=$r;if(!$sh)continue;$c=$contracts[$row['contract']]??[];$mt=0.;foreach((array)($sh['millActuals']??[]) as $a)$mt+=(float)($a['netKg']??$a['documentNetKg']??$a['millNetKg']??$a['weight']??$a['kg']??0)/1000;
        $invoice=(string)($sh['commercial']['invoiceNo']??'');$packs=(array)($c['packings']??[]);$rates=[];foreach($packs as $p){$inc=strtoupper((string)($c['incoterm']??'FOB'));$rates[]=((float)($p['contractRate']??0))?:((float)($p['price']??0)+($inc==='FOB'?0:(float)($p['freight']??0))+($inc==='CIF'?(float)($p['insurance']??0):0));}$rates=array_values(array_unique($rates));
        $contractPrice=count($rates)===1?$rates[0]:null;
        if($contractPrice===null&&$mt>0){$value=0.;$priced=0.;foreach((array)($sh['millActuals']??[]) as $a){$weight=(float)($a['netKg']??$a['documentNetKg']??$a['millNetKg']??$a['weight']??$a['kg']??0)/1000;if($weight<=0)continue;$matches=[];
            if(isset($a['packIndex'])&&isset($packs[(int)$a['packIndex']]))$matches=[$packs[(int)$a['packIndex']]];
            else foreach($packs as $pack){$brand=trim((string)($a['brand']??''));$packing=trim((string)($a['packing']??''));$size=(float)preg_replace('/[^0-9.]/','',$packing);if($brand!==''&&strcasecmp($brand,trim((string)($pack['brand']??'')))!==0)continue;if($size>0&&abs($size-(float)($pack['size']??0))>.00001)continue;$matches[]=$pack;}
            if(count($matches)!==1)continue;$pack=$matches[0];$inc=strtoupper((string)($c['incoterm']??'FOB'));$rate=(float)($pack['contractRate']??0);if($rate<=0)$rate=(float)($pack['price']??0)+($inc==='FOB'?0:(float)($pack['freight']??0))+($inc==='CIF'?(float)($pack['insurance']??0):0);if($rate<=0)continue;$value+=$weight*$rate;$priced+=$weight;
        }if(abs($priced-$mt)<.000001)$contractPrice=$value/$mt;}

        $out[$row['id']]=$row+['invoice'=>$invoice,'invoiceDate'=>$sh['commercial']['date']??'','quantityMT'=>round($mt,6),'contractPrice'=>$contractPrice,'currency'=>$c['currency']??'USD','incoterm'=>$c['incoterm']??'','commodity'=>$c['commodity']??'RICE','product'=>$c['product']??'','completed'=>!empty($sh['completed']),'invoiceSaved'=>!empty($sh['commercial']['saved'])];
    }return $out;
}
function dt_deal(array $b,array $parties):array {
    $partyId=gm_text($b['partyId']??'',120);$party=null;foreach($parties as $r)if((string)$r['id']===$partyId)$party=$r;if(!$party)throw new DomainException('Select an active fellow exporter from the Directors Fellow Exporter master.');
    $d=['entity'=>dt_entity($b['entity']??''),'date'=>gm_date($b['date']??''),'direction'=>dt_enum($b['direction']??'',['PURCHASE','SALE'],'purchase from or sale through exporter'),'arrangement'=>dt_enum($b['arrangement']??'',['FIXED','SETTLEMENT','EX_MILL','PARTNERSHIP','MARGIN'],'fixed price, quantity settlement, local ex-mill or shipment partnership'),'partyId'=>$partyId,'party'=>$party['name'],'currency'=>dt_enum($b['currency']??'USD',['USD','PKR'],'USD or PKR'),'price'=>dt_positive($b['price']??null,'agreed price per MT'),'quantityMT'=>dt_positive($b['quantityMT']??null,'contract quantity MT'),'incoterm'=>dt_enum($b['incoterm']??'',['FOB','CNF','CIF','EX_MILL'],'FOB, CNF, CIF or ex-mill')];
    dt_validate_arrangement($d,$b);
