    $profitTotal=0.;$goodsComplete=true;
    $rows=[];$total=0.;$loaded=0.;$warnings=[];$native=$d['direction']==='SALE'?dt_native_state($d,$nativeSales,$date):null;
    $orderedLoadings=(array)($d['loadings']??[]);usort($orderedLoadings,static fn($a,$b)=>strcmp($a['date'],$b['date'])?:strcmp($a['id'],$b['id']));foreach($orderedLoadings as $load){if($load['date']>$date)continue;$qty=$load['quantityMT'];$loaded+=$qty;$lot=$lots[$load['shipmentId']]??null;$sourceReady=true;if($native){$physicalByDate=0.;foreach($native['loads'] as $n)if($n['date']<=$load['date'])$physicalByDate+=$n['quantityMT'];if($loaded>$physicalByDate+.000001){$sourceReady=false;$warnings[]=$load['invoiceRef'].': dated own Mill dispatch must cover the invoice contribution by its actual loading date.';}}if($d['direction']==='SALE'&&$d['arrangement']==='SETTLEMENT'&&isset($load['externalPriceConfirmed'])&&!$load['externalPriceConfirmed']){$sourceReady=false;$warnings[]=$load['invoiceRef'].': Directors must confirm the other exporter contract price and statement.';}if($d['direction']==='PURCHASE'){if(!$lot||$lot['quantityMT']<=0){$sourceReady=false;$warnings[]=$load['invoiceRef'].': saved commercial invoice is unavailable.';}else{$load['totalInvoiceMT']=$lot['quantityMT'];$load['contractPrice']=$lot['contractPrice'];$load['contractCurrency']=$lot['currency'];$allocated=0.;foreach(array_filter((array)($s['exporterDeals']??[]),static fn($row)=>($row['status']??'')!=='Deleted') as $other)foreach((array)($other['loadings']??[]) as $l)if(($l['shipmentId']??'')===$load['shipmentId']&&$l['date']<=$date)$allocated+=$l['quantityMT'];if($allocated>$lot['quantityMT']+.000001||($d['arrangement']==='SETTLEMENT'&&($lot['contractPrice']===null||$lot['contractPrice']<=0))){$sourceReady=false;$warnings[]=$load['invoiceRef'].': reconcile revised invoice weights or original contract packing rates.';}}}$share=$load['totalInvoiceMT']>0?$qty/$load['totalInvoiceMT']:0;$actual=$lot?dt_expenses($s,$lot,$date):($load['externalExpenses']??[]);$advice=$lot?dt_advice($s,$lot,$date):[];
        $components=[];foreach($actual as $a)$components[$a['category']]=($components[$a['category']]??0)+($d['direction']==='SALE'&&($a['scope']??'')==='OUR_SHARE'&&$share>0?$a['amountPKR']/$share:$a['amountPKR']);
        $estimate=$d['fobEstimateUSDPerMT']*$load['totalInvoiceMT']*$d['fx'];$fob=0.;foreach($components as $kind=>$amount)if(!in_array($kind,['FREIGHT','INSURANCE','BANK'],true))$fob+=$amount;
        $invalid=count(array_filter($actual,static fn($a)=>!empty($a['invalidAllocation'])))>0;if($invalid)$warnings[]=$load['invoiceRef'].': a linked expense was amended or reversed; reconcile its allocation.';$actualReviewed=!$invalid&&!empty($load['expensesComplete'])&&isset($load['reviewHash'])&&hash_equals($load['reviewHash'],dt_source_hash($s,$load,$lots,$date,$native?dt_review_context($s,$d,$nativeSales,min($date,$load['date'])):[]));$fobTotal=$actualReviewed?$fob:max($fob,$estimate);$freightTotal=$d['incoterm']==='FOB'?0:($components['FREIGHT']??($actualReviewed?0:($d['freightEstimateUSDPerMT']*$load['totalInvoiceMT']*$d['fx'])));$insurance=$d['incoterm']==='CIF'?($components['INSURANCE']??($actualReviewed?0:($d['insuranceEstimateUSDPerMT']*$load['totalInvoiceMT']*$d['fx']))):0;
        $deduction=array_sum(array_column($advice,'amountPKR'))+($components['BANK']??0);$fraction=min(1.,array_sum(array_column($advice,'invoiceFraction')));$effectiveFX=$d['fx']*(1-$fraction);foreach($advice as $a)$effectiveFX+=$a['realizationRate']*$a['invoiceFraction'];if($fraction>=1&&array_sum(array_column($advice,'invoiceFraction'))>1.000001)throw new DomainException('Credit advice allocations exceed the invoice; reconcile the source receipts.');$adjustments=0.;foreach((array)($load['adjustments']??[]) as $a)$adjustments+=$a['amountPKR'];
        if($d['arrangement']==='FIXED'){$gross=$qty*$d['price']*($d['currency']==='USD'?$d['fx']:1);$costs=$d['direction']==='SALE'?($fobTotal+$freightTotal+$insurance+$deduction)*$share:($freightTotal+$insurance)*$share;$amount=$gross-$costs-$adjustments;}
        else{$rate=$load['contractPrice'];$gross=$qty*$rate*($load['contractCurrency']==='USD'?$effectiveFX:1);$pendingDeduction=$gross*(1-$fraction)*$d['bankEstimatePct']/100;$costs=($fobTotal+$freightTotal+$insurance+$deduction)*$share+($d['direction']==='PURCHASE'?$pendingDeduction:0);$amount=$gross-$costs-$adjustments;}
